#!/usr/bin/env bash
# Fills the GitHub Environment secrets for one environment. Runs on the OWNER'S / DEVOPS LAPTOP (not the VM, never agy).
#   bash infra/scripts/provision-secrets.sh staging|production
#
# * Secrets that people created (Cloudflare is NOT here; it is only used by dns.sh) are read BY NAME from
#   D:\Projects\Project_credentials\BasaManager.env and copied into the environment.
# * Secrets the agents own (passwords, JWT, cookie/URL keys, VAPID) are generated with a CSPRNG the first time and
#   NEVER regenerated by this script (that would log everybody out / lock the database). To rotate one:
#   ROTATE=JWT_SECRET bash infra/scripts/provision-secrets.sh staging, then redeploy (docs/operations/rotate-a-secret.md).
# * Nothing is printed except secret NAMES and whether they were generated, copied or kept.
set -euo pipefail

TARGET="${1:?usage: provision-secrets.sh staging|production}"
case "$TARGET" in staging|production) ;; *) echo "target must be staging or production" >&2; exit 1 ;; esac
REPO="${REPO:-RHRONY05/BasaManager}"
CREDS="${CREDS_FILE:-/d/Projects/Project_credentials/BasaManager.env}"
# The pipeline uses its OWN key (deploy user only); the admin key basamanager_ed25519 (azureuser, sudo) is never uploaded.
SSH_KEY_FILE="${DEPLOY_KEY_FILE:-$HOME/.ssh/basamanager_deploy_ed25519}"
ROTATE="${ROTATE:-}"

[ -f "$CREDS" ] || { echo "credentials file not found: $CREDS" >&2; exit 1; }
# Read the file as DATA (KEY=value per line), never as shell code, and do not export anything.
while IFS='=' read -r k v; do
  case "$k" in '' | \#*) continue ;; esac
  [[ "$k" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || continue
  # Strip one matching pair of quotes only (a lone quote belongs to the value).
  if [[ ${#v} -ge 2 && $v == \"*\" ]]; then v="${v:1:-1}"; elif [[ ${#v} -ge 2 && $v == \'*\' ]]; then v="${v:1:-1}"; fi
  printf -v "$k" '%s' "$v"
done < <(tr -d '\r' < "$CREDS")

EXISTING="$(gh secret list --env "$TARGET" --repo "$REPO" --json name -q '.[].name')"
has() { printf '%s\n' "$EXISTING" | grep -qx "$1"; }
rotating() { case ",$ROTATE," in *",$1,"*) return 0 ;; *) return 1 ;; esac; }
put() { # name value status
  printf '%s' "$2" | gh secret set "$1" --env "$TARGET" --repo "$REPO" >/dev/null
  printf '  %-28s %-10s (length %s)\n' "$1" "$3" "${#2}"
}

echo "== generated secrets ($TARGET)"
for n in POSTGRES_PASSWORD BM_APP_PASSWORD BM_WORKER_PASSWORD BM_READONLY_PASSWORD REDIS_PASSWORD; do
  if has "$n" && ! rotating "$n"; then printf '  %-28s kept\n' "$n"; else put "$n" "$(openssl rand -hex 24)" generated; fi
done
for n in JWT_SECRET STORAGE_URL_SECRET; do
  if has "$n" && ! rotating "$n"; then printf '  %-28s kept\n' "$n"; else put "$n" "$(openssl rand -hex 32)" generated; fi
done
if has SEED_PASSWORD && ! rotating SEED_PASSWORD; then printf '  %-28s kept\n' SEED_PASSWORD; else
  put SEED_PASSWORD "$(openssl rand -base64 18 | tr -d '/+=' | cut -c1-20)Aa1" generated
fi
if has VAPID_PUBLIC_KEY && has VAPID_PRIVATE_KEY && ! rotating VAPID_PRIVATE_KEY; then
  printf '  %-28s kept\n' "VAPID_*"
else
  # VAPID key pair = P-256 key, base64url (Web Push standard; same format as `web-push generate-vapid-keys`).
  KEYS="$(node -e '
    const c = require("node:crypto"); const e = c.createECDH("prime256v1"); e.generateKeys();
    const b = (x) => x.toString("base64url");
    process.stdout.write(b(e.getPublicKey()) + " " + b(e.getPrivateKey()));')"
  put VAPID_PUBLIC_KEY "${KEYS%% *}" generated
  put VAPID_PRIVATE_KEY "${KEYS##* }" generated
fi

echo "== copied from the credentials file"
for n in CLOUDINARY_CLOUD_NAME CLOUDINARY_API_KEY CLOUDINARY_API_SECRET RESEND_API_KEY \
  GOOGLE_OAUTH_CLIENT_ID GOOGLE_OAUTH_CLIENT_SECRET SSLCOMMERZ_STORE_ID SSLCOMMERZ_STORE_PASSWORD \
  SENTRY_DSN_API SENTRY_DSN_WORKER SENTRY_DSN_WEB SENTRY_AUTH_TOKEN SENTRY_ORG; do
  v="${!n:-}"
  [ -n "$v" ] || { echo "  $n is empty in the credentials file" >&2; exit 1; }
  put "$n" "$v" copied
done

echo "== deploy access"
[ -n "${DEPLOY_HOST:-}" ] || { echo "export DEPLOY_HOST=<vm ip> first" >&2; exit 1; }
put DEPLOY_HOST "$DEPLOY_HOST" set
put DEPLOY_SSH_KEY "$(cat "$SSH_KEY_FILE")
" set
# The VM's own host key, read over the authenticated SSH connection (not trust-on-first-use from the runner).
HOSTKEY="$(ssh -i "$SSH_KEY_FILE" -o StrictHostKeyChecking=yes "deploy@$DEPLOY_HOST" 'cat /etc/ssh/ssh_host_ed25519_key.pub' | awk '{print $1" "$2}')"
put DEPLOY_KNOWN_HOSTS "$DEPLOY_HOST $HOSTKEY" set

if [ -n "${AZURE_BACKUP_ACCOUNT:-}" ] && [ -f "${BACKUP_SAS_FILE:-.secrets/backup-sas}" ]; then
  echo "== backups"
  put AZURE_BACKUP_ACCOUNT "$AZURE_BACKUP_ACCOUNT" set
  put AZURE_BACKUP_SAS "$(tr -d '\r\n' < "${BACKUP_SAS_FILE:-.secrets/backup-sas}")" set
else
  echo "== backups: export AZURE_BACKUP_ACCOUNT and keep the SAS file at .secrets/backup-sas to set them"
fi
